covergroup cg_fifo_depth @(posedge clk iff (!rst));
  option.per_instance = 1;
  cp_fifo_status: coverpoint fifo_count {
    bins empty_bin = {0};
    bins almost_empty = {1};
    bins mid_range = {[2:14]};
    bins almost_full = {15};
    bins full_bin = {16};
  }
  cp_trans_empty_to_not: coverpoint empty {
    bins empty_to_active = (1 => 0);
    bins active_to_empty = (0 => 1);
  }
  cp_simultaneous_rw: cross cp_fifo_status, coverpoint (wr_en && rd_en) {
    bins rw_while_full = binsof(cp_fifo_status.full_bin) && binsof(coverpoint (wr_en && rd_en)) intersect {1'b1};
    bins rw_while_empty = binsof(cp_fifo_status.empty_bin) && binsof(coverpoint (wr_en && rd_en)) intersect {1'b1};
  }
endgroup

